4	import java.io.IOException;
5	import java.io.UncheckedIOException;
6	import java.nio.charset.StandardCharsets;
7	import java.nio.file.Files;
8	import java.nio.file.Path;
9	import java.nio.file.StandardOpenOption;
10	import org.springframework.beans.factory.annotation.Value;
11	import org.springframework.stereotype.Service;
12	import org.springframework.transaction.support.TransactionSynchronization;
13	import org.springframework.transaction.support.TransactionSynchronizationManager;
14	
15	/**
16	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
17	 * so tests can assert side-effects by reading that file — the second test-assertion channel
18	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
19	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
20	 *
21	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
22	 * SYNC) so a test reads the record immediately.
23	 */
24	@Service
25	public class Audit {
26	
27	    private final Path file;
28	
29	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
30	        this.file = Path.of(path);
31	    }
32	
33	    /** Append one audit record. Tests assert the exact line(s) in the file. */
34	    public synchronized void record(String entry) {
35	        try {
36	            Path parent = file.toAbsolutePath().getParent();
37	            if (parent != null) {
38	                Files.createDirectories(parent);
39	            }
40	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
41	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
42	        } catch (IOException e) {
43	            throw new UncheckedIOException(e);
44	        }
45	    }
46	
47	    /**
48	     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
49	     * the fields, separated by single spaces. Inside a transaction the record is written only once
50	     * it commits, so a change that is refused or rolled back writes nothing.
51	     */
52	    public void change(String event, String sheetId, String user, String... fields) {
53	        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
54	        for (String field : fields) {
55	            entry.append(' ').append(field);
56	        }
57	        String line = entry.toString();
58	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
59	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
60	                @Override
61	                public void afterCommit() {
62	                    record(line);
63	                }
64	            });
65	        } else {
66	            record(line);
67	        }
68	    }
69	
70	    /** Truncate the audit file. */
71	    public synchronized void clear() {
72	        try {
73	            Files.deleteIfExists(file);
74	        } catch (IOException e) {
75	            throw new UncheckedIOException(e);
76	        }
77	    }
