125	import net.officefloor.hq.app.person.Person;
126	import net.officefloor.hq.app.person.PersonRepository;
127	import net.officefloor.hq.app.sheet.SheetService;
128	import org.springframework.http.HttpStatus;
129	import org.springframework.stereotype.Service;
130	import org.springframework.transaction.annotation.Transactional;
131	import org.springframework.web.server.ResponseStatusException;
132	
133	/**
134	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
135	 * missing note is stored empty.
136	 */
137	@Service
138	public class ClaimService {
139	
140	    private final ClaimRepository claims;
141	    private final PersonRepository people;
142	    private final SheetService sheets;
143	    private final Audit audit;
144	
145	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets, Audit audit) {
146	        this.claims = claims;
147	        this.people = people;
148	        this.sheets = sheets;
149	        this.audit = audit;
150	    }
151	
152	    @Transactional(readOnly = true)
153	    public List<Claim> list(String sheetId) {
154	        return claims.findBySheetIdOrderByIdDesc(sheetId);
155	    }
156	
157	    @Transactional
158	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
159	        sheets.load(sheetId, user);
160	        Person person = people.findByIdAndSheetId(personId, sheetId)
161	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
162	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount),
163	                date != null ? date : sheets.today(sheetId), note != null ? note : ""));
164	        record("CLAIM_ADDED", user, person, claim);
165	        return claim;
166	    }
167	
168	    @Transactional
169	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
170	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
171	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
172	        claim.setAmount(scaled(amount));
173	        claim.setDate(date != null ? date : sheets.today(sheetId));
174	        claim.setNote(note != null ? note : "");
175	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
176	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
177	        record("CLAIM_EDITED", user, person, claim);
178	        return claim;
179	    }
180	
181	    /** Move a claim to the next status; a change its status does not allow is refused (409). */
182	    @Transactional
183	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
184	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
185	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
186	        if (!claim.getStatus().canBecome(next)) {
187	            throw new ResponseStatusException(HttpStatus.CONFLICT,
188	                    "A " + claim.getStatus() + " claim cannot become " + next);
189	        }
190	        claim.setStatus(next);
191	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
192	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
193	        record(switch (next) {
194	            case OPEN -> "CLAIM_OPENED";
195	            case SETTLED -> "CLAIM_SETTLED";
196	            case VOID -> "CLAIM_VOIDED";
197	            case DRAFT -> throw new IllegalStateException();
198	        }, user, person, claim);
199	        return claim;
200	    }
201	
202	    /** Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. */
203	    private void record(String event, String user, Person person, Claim claim) {
204	        audit.change(event, claim.getSheetId(), user, "person=" + person.getName(),
205	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate());
206	    }
207	
208	    private static BigDecimal scaled(BigDecimal amount) {
209	        return amount.setScale(2, RoundingMode.UNNECESSARY);
210	    }
211	}
