420	/**
421	 * A claim's status. It starts as DRAFT, can be opened and then settled; a DRAFT or OPEN claim can
422	 * be voided. SETTLED and VOID are final. Only OPEN and SETTLED claims count toward the totals.
423	 */
424	public enum ClaimStatus {
425	    DRAFT, OPEN, SETTLED, VOID;
426	
427	    /** Whether a claim in this status may move to the given one. */
428	    public boolean canBecome(ClaimStatus next) {
429	        return switch (next) {
430	            case OPEN -> this == DRAFT;
431	            case SETTLED -> this == OPEN;
432	            case VOID -> this == DRAFT || this == OPEN;
433	            case DRAFT -> false;
434	        };
435	    }
