936	
937	/**
938	 * Loads sheets by id; a sheet never loaded before is created empty. The real clock is read only
939	 * here, to start a new sheet's "today"; everything else uses {@link #today(String)}.
940	 */
941	@Service
942	public class SheetService {
943	
944	    private final SheetRepository sheets;
945	    private final Clock clock = Clock.systemDefaultZone();
946	
947	    public SheetService(SheetRepository sheets) {
948	        this.sheets = sheets;
949	    }
950	
951	    @Transactional
952	    public Sheet load(String id, String user) {
953	        return sheets.findById(id).orElseGet(() -> create(id, user));
954	    }
955	
956	    /** The sheet's "today": the date every decision and default date in the sheet uses. */
957	    @Transactional(readOnly = true)
958	    public LocalDate today(String id) {
959	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
960	    }
961	
962	    @Transactional
963	    public Sheet setToday(String id, String user, LocalDate today) {
964	        Sheet sheet = load(id, user);
965	        sheet.setToday(today);
966	        return sheet;
967	    }
968	
969	    private Sheet create(String id, String user) {
970	        try {
971	            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock)));
972	        } catch (DataIntegrityViolationException e) {
973	            // Another user loaded the same new sheet at the same moment.
974	            return sheets.findById(id).orElseThrow(() -> e);
975	        }
